import { execution } from '@dynatrace-sdk/automation-utils';

export default async function ({ executionId }) {
  const ex = await execution(executionId);
  const { costPerEnv, costDate, month } = await ex.result('fetching_costs');

  const byCapability = {};
  const byEnvironment = {};
  const byEnvironmentCapability = {};
  let currency = 'USD';

  for (const env of costPerEnv) {
    const envId = env.environmentId || env.clusterId || 'unknown';
    if (!byEnvironment[envId]) byEnvironment[envId] = { total: 0 };
    if (!byEnvironmentCapability[envId]) byEnvironmentCapability[envId] = {};

    for (const { capabilityName, capabilityKey, value, currencyCode } of env.cost || []) {
      currency = currencyCode || currency;

      // merge by capabilityKey — same capability can appear across multiple env entries
      if (!byCapability[capabilityKey]) byCapability[capabilityKey] = { capabilityName, value: 0 };
      byCapability[capabilityKey].value += value;

      byEnvironment[envId].total += value;

      if (!byEnvironmentCapability[envId][capabilityKey]) byEnvironmentCapability[envId][capabilityKey] = { capabilityName, value: 0 };
      byEnvironmentCapability[envId][capabilityKey].value += value;
    }
  }

  const total = Object.values(byCapability).reduce((sum, c) => sum + c.value, 0);

  const summary = {
    byCapability,            // { FULLSTACK_MONITORING: { capabilityName, value }, ... }
    byEnvironment,           // { abc12345: { total }, ... }
    byEnvironmentCapability, // { abc12345: { FULLSTACK_MONITORING: { capabilityName, value }, ... }, ... }
    total,
    currency,
  };

  console.log(`Aggregated ${Object.keys(byCapability).length} capabilities across ${Object.keys(byEnvironment).length} environments — total ${total.toFixed(2)} ${currency}`);

  return { summary, costDate, month };
}

import { credentialVaultClient } from "@dynatrace-sdk/client-classic-environment-v2";

const TOKEN_URL       = 'https://sso.dynatrace.com/sso/oauth2/token';
const CREDENTIAL_NAME = 'DPS Budget Tracker OAuth';
const BASE_URL        = 'https://api.dynatrace.com';

const RETRY_STATUSES = new Set([429, 500, 502, 503, 504]);
const sleep = ms => new Promise(resolve => setTimeout(resolve, ms));

function parseCredentials(username, password) {
  const lastDot = password.lastIndexOf(".");
  return {
    accountUuid: username,
    clientId: password.substring(0, lastDot),
    clientSecret: password,
  };
}

async function getOAuthToken(clientId, clientSecret, accountUuid) {
  const resp = await fetch(TOKEN_URL, {
    method: 'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body: new URLSearchParams({
      grant_type: 'client_credentials',
      client_id: clientId,
      client_secret: clientSecret,
      scope: 'account-uac-read',
      resource: `urn:dtaccount:${accountUuid}`,
    }),
  });
  if (!resp.ok) throw new Error(`Token request failed: ${await resp.text()}`);
  return (await resp.json()).access_token;
}

async function apiGet(url, token, params = {}) {
  const qs = new URLSearchParams(params).toString();
  const fullUrl = qs ? `${url}?${qs}` : url;

  for (let attempt = 0; attempt < 3; attempt++) {
    const resp = await fetch(fullUrl, { headers: { Authorization: `Bearer ${token}` } });
    if (resp.ok) return resp.json();
    if (!RETRY_STATUSES.has(resp.status) || attempt === 2) {
      throw new Error(`GET ${url} failed (${resp.status}): ${await resp.text()}`);
    }
    await sleep(2 ** attempt * 1000);
  }
}

async function getActiveSubscription(token, accountUuid) {
  const data = await apiGet(`${BASE_URL}/sub/v2/accounts/${accountUuid}/subscriptions`, token);
  const active = (data.data || []).filter(s => s.status === 'ACTIVE' && s.type === 'REGULAR');
  if (active.length === 0) throw new Error('No active REGULAR subscription found for this account.');
  return active[0];
}

function yesterdayRange() {
  const now = new Date();
  const y = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate() - 1));
  const fmt = d => d.toISOString().replace('.000Z', 'Z');
  return {
    start: fmt(new Date(Date.UTC(y.getUTCFullYear(), y.getUTCMonth(), y.getUTCDate(), 0, 0, 0))),
    end:   fmt(new Date(Date.UTC(y.getUTCFullYear(), y.getUTCMonth(), y.getUTCDate(), 23, 59, 59))),
    costDate:  y.toISOString().substring(0, 10),
    month: y.toISOString().substring(0, 7),
  };
}

async function getCostPerEnvironment(token, accountUuid, subscriptionUuid, startTime, endTime) {
  const url = `${BASE_URL}/sub/v3/accounts/${accountUuid}/subscriptions/${subscriptionUuid}/environments/cost`;
  let params = { startTime, endTime };
  const results = [];

  while (true) {
    const body = await apiGet(url, token, params);
    results.push(...(body.data || []));
    if (!body.nextPageKey) break;
    params = { ...params, 'page-key': body.nextPageKey };
  }

  return results;
}

export default async function ({ executionId }) {
  const credList = await credentialVaultClient.listCredentials({ name: `"${CREDENTIAL_NAME}"` });
  if (!credList || credList.totalCount === 0) {
    throw new Error(`Credential "${CREDENTIAL_NAME}" not found. Create it with username=accountUuid, password=clientSecret.`);
  }
  const creds = await credentialVaultClient.getCredentialsDetails({ id: credList.credentials[0].id });
  const { accountUuid, clientId, clientSecret } = parseCredentials(creds.username, creds.password);

  const token = await getOAuthToken(clientId, clientSecret, accountUuid);
  console.log('OAuth token obtained');

  const subscription = await getActiveSubscription(token, accountUuid);
  console.log(`Subscription: ${subscription.name} (${subscription.uuid})`);

  const { start, end, costDate, month } = yesterdayRange();
  console.log(`Fetching costs for ${costDate}`);

  const costPerEnv = await getCostPerEnvironment(token, accountUuid, subscription.uuid, start, end);
  console.log(`Fetched ${costPerEnv.length} environment entries`);

  return { costPerEnv, costDate, month };
}

import { execution } from '@dynatrace-sdk/automation-utils';
import { businessEventsClient } from "@dynatrace-sdk/client-classic-environment-v2";

export default async function ({ executionId }) {
  const ex = await execution(executionId);
  const { summary, costDate, month } = await ex.result('aggregate_data');

  const { byCapability, byEnvironment, byEnvironmentCapability, total, currency } = summary;
  const base = { 'event.provider': 'dps.budget.tracker', costDate, month, currencyCode: currency };
  let count = 0;

  for (const [capabilityKey, { capabilityName, value }] of Object.entries(byCapability)) {
    await businessEventsClient.ingest({
      body: { ...base, 'event.type': 'dps.cost.daily.capability', capabilityKey, capabilityName, value },
      type: 'application/json; charset=utf-8',
    });
    count++;
  }

  for (const [environmentId, { total: envTotal }] of Object.entries(byEnvironment)) {
    await businessEventsClient.ingest({
      body: { ...base, 'event.type': 'dps.cost.daily.environment', environmentId, value: envTotal },
      type: 'application/json; charset=utf-8',
    });
    count++;
  }

  for (const [environmentId, capabilities] of Object.entries(byEnvironmentCapability)) {
    for (const [capabilityKey, { capabilityName, value }] of Object.entries(capabilities)) {
      await businessEventsClient.ingest({
        body: { ...base, 'event.type': 'dps.cost.daily.environment.capability', environmentId, capabilityKey, capabilityName, value },
        type: 'application/json; charset=utf-8',
      });
      count++;
    }
  }

  await businessEventsClient.ingest({
    body: { ...base, 'event.type': 'dps.cost.daily.total', value: total },
    type: 'application/json; charset=utf-8',
  });
  count++;

  console.log(`${count} biz events sent — daily total ${total} ${currency}`);

  return { costDate, month, dailyTotal: total, currency, eventsSent: count };
}
